354-  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
355-  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
356-  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
357-  const r = row(page, id);
358-  const shows_ = async () => {
359-    if (f.name !== undefined && plainName(await shown(r.getByTestId('person-name'))) !== f.name.trim()) return false;
360-    if (grade !== undefined && await shown(r.getByTestId('person-grade')) !== grade) return false;
361-    if (terms !== undefined && await shown(r.getByTestId('person-terms')) !== terms) return false;
362-    return !(await page.getByTestId('person-form-error').isVisible().catch(() => false));
363-  };
364-  // a save the row cannot show (the values it checks are already there) is judged by its error
365-  const already = await shows_();
366-  await fillPersonForm(page, f);
367-  await page.getByTestId('person-form-submit').click();
368-  return until(page, shows_, page.getByTestId('person-form-error'), 'save person', already);
--
